pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Setup: make actor the owner by deploying with prank
        vm.startPrank(actor);
        C local = new C();
        vm.stopPrank();
        // Test: actor calls suicideAnyone
        vm.prank(actor);
        try local.sudicideAnyone() {
            // After successful call, contract must be self-destructed (code length zero)
            assertTrue(address(local).code.length == 0);
        } catch {
            // If it reverts, the invariant is trivially maintained for this path;
            // but the buggy version reverts for the owner, so we assert the opposite
            assertTrue(address(local).code.length > 0);
        }
    }
}

