pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address notOwner) public {
        vm.assume(owner != address(0) && notOwner != address(0));
        vm.assume(owner != notOwner);
        vm.assume(owner != address(c) && notOwner != address(c));

        // Warp owner to be the smartfix_owner
        vm.prank(owner);
        c.sudicideAnyone();

        // After owner call, reference self-destructs (code length 0),
        // mutant reverts the call but leaves contract alive (code length > 0).
        uint256 codeLen;
        assembly { codeLen := extcodesize(c) }
        assertTrue(codeLen == 0);
    }
}

