pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        vm.prank(owner);
        // Call in a try/catch to handle the revert in the mutant.
        bool initialCallOk;
        try c.sudicideAnyone() { initialCallOk = true; } catch { initialCallOk = false; }
        // After the call, attempt a low-level call with no calldata.
        // In the reference, the contract is destroyed: call succeeds returning true with empty data.
        // In the mutant, the contract is alive but has no fallback; call fails reverting.
        (bool success, ) = address(c).call("");
        // For the reference, initialCallOk is true and success is true.
        // For the mutant, initialCallOk is false and success is false.
        assertTrue(initialCallOk == success);
    }
}

